sp_widget.client_script:
api.controller = function($scope, $window, $rootScope, $document, spUtil) {
    var c = this;

    // Variável de estado para mostrar/esconder o botão
    c.showScrollToTop = false;

    // Lógica de Contraste (mantida)
	$scope.contrastIsActive = false;
	var contrastListener = $rootScope.$on('sp.contrast.toggled', function(event, data) {
        $scope.contrastIsActive = data.enabled;
    });
    $scope.$on('$destroy', contrastListener); 

      $scope.goToTop= function()
	{
		spUtil.scrollTo('.sp-scroll', 300);
	}
};

sp_widget.css:
/* Variáveis para o botão */
$button-size: 50px;
$button-color: #ffffff;
$background-color: #4773C6; // Azul

.scroll-to-top-container {
    /* CORREÇÃO AGRESSIVA DE POSICIONAMENTO */
    position: fixed !important;
    bottom: 30px !important; 
    right: 30px !important;
    z-index: 9999 !important; /* Aumentamos o z-index para garantir a visibilidade */

    /* DESIGN DO CÍRCULO */
    width: $button-size;
    height: $button-size;
    border-radius: 50%;
    background-color: $background-color;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
    cursor: pointer;

    /* CENTRALIZAÇÃO DO ÍCONE */
    display: flex; /* Mantemos o flex para centralizar, mas sem o !important aqui */
    justify-content: center;
    align-items: center;

    /* ESTILIZAÇÃO DA SETA (Font Awesome) */
    .fa-arrow-up {
        font-size: 20px;
        color: $button-color;
    }

    /* ANIMAÇÃO DE HOVER */
    transition: background-color 0.3s ease, transform 0.3s ease;

    &:hover {
        background-color: darken($background-color, 10%);
        transform: scale(1.05);
    }
}

// Estilo para Alto Contraste
.contrast-mode.scroll-to-top-container {
    background-color: #ffffff !important;
    border: 2px solid #000000 !important;
    box-shadow: none !important;

    .fa-arrow-up {
        color: #000000 !important;
    }

    &:hover {
        background-color: #cccccc !important;
        transform: scale(1.05);
    }
}
